mapper.select:
SELECT cr.id, cr.user_id AS userId, u.username, u.phone, cr.real_name AS realName, cr.craft_type AS craftType, cr.inheritance, cr.intro, cr.cover, cr.audit_status AS auditStatus, cr.reject_reason AS rejectReason, cr.audit_time AS auditTime, cr.follower_count AS followerCount, cr.create_time AS createTime, u.status, IFNULL(g.cnt, 0) AS goodsCount, IFNULL(co.cnt, 0) AS courseCount FROM craftsman cr JOIN `user` u ON u.id = cr.user_id AND u.deleted = 0 LEFT JOIN ( SELECT craftsman_id, COUNT(*) AS cnt FROM goods WHERE deleted = 0 AND status = 1 AND audit_status = 1 GROUP BY craftsman_id ) g ON g.craftsman_id = cr.id LEFT JOIN ( SELECT craftsman_id, COUNT(*) AS cnt FROM course WHERE deleted = 0 GROUP BY craftsman_id ) co ON co.craftsman_id = cr.id WHERE cr.deleted = 0
AND cr.audit_status = #{q.auditStatus}
AND cr.craft_type = #{q.craftType}
AND u.status = #{q.status}
AND (cr.real_name LIKE CONCAT('%', #{q.keyword}, '%') OR u.phone LIKE CONCAT('%', #{q.keyword}, '%') OR u.username LIKE CONCAT('%', #{q.keyword}, '%') OR cr.craft_type LIKE CONCAT('%', #{q.keyword}, '%'))
AND cr.create_time >= #{q.startTime}
AND cr.create_time <= #{q.endTime}
ORDER BY cr.follower_count DESC, cr.id ASC ORDER BY goodsCount DESC, cr.id ASC ORDER BY cr.create_time DESC, cr.id DESC ORDER BY (cr.audit_status = 0) DESC, cr.create_time ASC, cr.id ASC
